                            {% endfor %}
                        </ul>
                    {% else %}
                        <p style="color: #666; font-style: italic;">No tasks in this list yet.</p>
                    {% endif %}
                </div>
            {% endfor %}
        {% else %}
            <p style="text-align: center; color: #666;">No to-do lists found. Create one above!</p>
        {% endif %}
    </div>
</body>
</html>
