            justify-content: space-between;
            align-items: center;
        }
        ul {
            list-style-type: none;
            padding: 0;
        }
        li {
            display: flex;
            justify-content: space-between;
            align-items: center;
            padding: 8px 0;
            border-bottom: 1px solid #eee;
        }
        .completed {
            text-decoration: line-through;
            color: #888;
        }
        .task-actions form {
            display: inline;
            margin-left: 5px;
        }
    </style>
</head>
<body>
    <div class="container">
        <h1>My To-Do Lists</h1>

        <!-- Create List Form -->
        <div class="form-group">
            <form action="{{ url_for('create_list') }}" method="POST">
                <input type="text" name="name" placeholder="New List Name..." required>
                <button type="submit">Create List</button>
            </form>
        </div>

        <!-- Lists Display -->
        {% if lists %}
            {% for l in lists %}
                <div class="todo-list">
                    <h3>
                        {{ l.name }}
                        <form action="{{ url_for('delete_list', list_id=l.id) }}" method="POST" style="display:inline;">
                            <button type="submit" class="danger-btn">Delete List</button>
                        </form>
                    </h3>

                    <!-- Add Task Form -->
                    <form action="{{ url_for('add_task', list_id=l.id) }}" method="POST" style="margin-bottom: 10px;">
                        <input type="text" name="text" placeholder="New Task Description..." required style="width: 60%;">
                        <button type="submit">Add Task</button>
                    </form>

                    <!-- Tasks List -->
                    {% if l.tasks %}
                        <ul>
                            {% for t in l.tasks %}
                                <li>
                                    <span class="{% if t.completed %}completed{% endif %}">
                                        {{ t.text }}
                                    </span>
                                    <div class="task-actions">
                                        <form action="{{ url_for('toggle_task', list_id=l.id, task_id=t.id) }}" method="POST">
                                            <button type="submit">{% if t.completed %}Mark Incomplete{% else %}Mark Complete{% endif %}</button>
                                        </form>
                                        <form action="{{ url_for('delete_task', list_id=l.id, task_id=t.id) }}" method="POST">
                                            <button type="submit" class="danger-btn">Delete</button>
                                        </form>
                                    </div>
                                </li>
                            {% endfor %}
                        </ul>
                    {% else %}
                        <p style="color: #666; font-style: italic;">No tasks in this list yet.</p>
                    {% endif %}
                </div>
            {% endfor %}
        {% else %}
            <p style="text-align: center; color: #666;">No to-do lists found. Create one above!</p>
        {% endif %}
    </div>
</body>
</html>
'}
